head.b:skin:
/* IEU 이음유니언 기술 블로그 — ieu.co.kr 사이트와 같은 디자인 토큰 */
:root{--night:#070b18;--bg:#f4f7fb;--surface:#fff;--line:#e2e8f2;--text:#0e1528;--sub:#5a6478;--mute:#8b94a7;--cyan:#19c3ff;--blue:#2563ff;--grad:linear-gradient(120deg,#19c3ff 0%,#2f7bff 55%,#5a5cff 100%);--sans:'Pretendard','Malgun Gothic',system-ui,sans-serif;--display:'Sora','Pretendard',sans-serif;--mono:'JetBrains Mono',ui-monospace,monospace}
*{box-sizing:border-box}
html,body{margin:0;padding:0}
body{background:var(--bg);color:var(--text);font-family:var(--sans);-webkit-font-smoothing:antialiased}
a{color:var(--blue)}
img{max-width:100%;height:auto}
.wrap{max-width:1080px;margin:0 auto;padding-left:max(20px,env(safe-area-inset-left,0px));padding-right:max(20px,env(safe-area-inset-right,0px))}
.ieu-nav{position:sticky;top:0;z-index:50;background:rgba(7,11,24,.86);backdrop-filter:blur(12px);-webkit-backdrop-filter:blur(12px);border-bottom:1px solid rgba(255,255,255,.06)}
.ieu-nav .wrap{display:flex;align-items:center;justify-content:space-between;height:62px;gap:16px}
.ieu-logo{display:flex;align-items:center;gap:10px;color:#fff;text-decoration:none}
.ieu-logo img{width:30px;filter:drop-shadow(0 0 10px rgba(25,195,255,.45))}
.ieu-logo b{font-family:var(--display);letter-spacing:.06em}
.ieu-logo small{display:block;font-size:11px;color:#8fa0c4;font-weight:500}
.ieu-links{display:flex;align-items:center;gap:18px}
.ieu-links a{color:#b7c2dc;text-decoration:none;font-size:14px;font-weight:500}
.ieu-links a:hover{color:#fff}
.ieu-links .cta{padding:8px 15px;border-radius:999px;background:var(--grad);color:#fff;font-weight:600;white-space:nowrap}
.ieu-hero{position:relative;overflow:hidden;background:var(--night);color:#fff;padding:64px 0 76px}
.ieu-hero:before{content:"";position:absolute;width:700px;height:700px;right:-200px;top:-320px;background:radial-gradient(circle,rgba(25,195,255,.28),rgba(37,99,255,.1) 40%,transparent 70%)}
.ieu-hero .wrap{position:relative}
.ieu-kicker{font-family:var(--mono);font-size:12px;letter-spacing:.14em;color:var(--cyan);text-transform:uppercase}
.ieu-hero h1{font-size:clamp(30px,5vw,46px);font-weight:800;letter-spacing:-.03em;line-height:1.2;margin:12px 0 10px;word-break:keep-all}
.ieu-hero h1 span{background:var(--grad);-webkit-background-clip:text;background-clip:text;color:transparent}
.ieu-hero p{color:#aab6d1;line-height:1.8;max-width:560px;margin:0;word-break:keep-all}
.ieu-main{padding:48px 0 72px}
.ieu-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px}
.ieu-card{display:flex;flex-direction:column;background:var(--surface);border:1px solid var(--line);border-radius:20px;overflow:hidden;text-decoration:none;color:inherit;transition:transform .25s,box-shadow .25s}
.ieu-card:hover{transform:translateY(-4px);box-shadow:0 0 0 1px rgba(25,195,255,.25),0 18px 40px -12px rgba(37,99,255,.35)}
.ieu-thumb{aspect-ratio:16/9;background:var(--night) radial-gradient(circle at 70% 20%,rgba(25,195,255,.35),transparent 60%);display:grid;place-items:center;overflow:hidden}
.ieu-thumb img{width:100%;height:100%;object-fit:cover}
.ieu-thumb .ph{width:64px;opacity:.9;filter:drop-shadow(0 8px 18px rgba(25,195,255,.5))}
.ieu-body{padding:18px 18px 20px;display:flex;flex-direction:column;flex:1}
.ieu-meta{display:flex;gap:8px;align-items:center;flex-wrap:wrap;font-family:var(--mono);font-size:11px;color:var(--mute);margin-bottom:8px}
.ieu-tag{color:var(--blue);background:#e6efff;border-radius:999px;padding:3px 9px;text-decoration:none;font-family:var(--mono);font-size:11px}
.ieu-card h2{font-size:17px;line-height:1.45;margin:0 0 8px;font-weight:700;word-break:keep-all}
.ieu-card p{font-size:14px;color:var(--sub);line-height:1.7;margin:0;word-break:keep-all;display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden}
.ieu-empty{grid-column:1/-1;background:var(--surface);border:1px dashed var(--line);border-radius:20px;padding:48px 24px;text-align:center;color:var(--sub)}
.ieu-pager{display:flex;justify-content:space-between;gap:12px;margin-top:32px}
.ieu-pager a{padding:10px 18px;border-radius:999px;border:1px solid var(--line);background:#fff;color:var(--text);text-decoration:none;font-weight:600;font-size:14px}
.ieu-pager a:hover{border-color:var(--blue);color:var(--blue)}
.ieu-article{max-width:760px;margin:0 auto;background:var(--surface);border:1px solid var(--line);border-radius:24px;padding:44px}
.ieu-article .ieu-back{display:inline-block;font-size:14px;color:var(--sub);text-decoration:none;margin-bottom:18px}
.ieu-article h1{font-size:clamp(26px,4vw,36px);font-weight:800;letter-spacing:-.025em;line-height:1.3;margin:10px 0 14px;word-break:keep-all}
.ieu-content{font-size:16.5px;line-height:1.9;color:#243049;word-break:keep-all;overflow-wrap:anywhere}
.ieu-content h2{font-size:23px;margin:40px 0 12px;letter-spacing:-.02em}
.ieu-content h3{font-size:19px;margin:32px 0 10px}
.ieu-content img{border-radius:14px}
.ieu-content a{color:var(--blue)}
.ieu-content blockquote{margin:24px 0;padding:14px 18px;border-left:3px solid var(--cyan);background:#f2f7ff;border-radius:0 12px 12px 0;color:#34405a}
.ieu-content code{font-family:var(--mono);font-size:.88em;background:#eef3fb;padding:2px 6px;border-radius:6px}
.ieu-content pre{background:var(--night);color:#e3ebff;padding:18px;border-radius:14px;overflow-x:auto;line-height:1.6}
.ieu-content pre code{background:none;padding:0;color:inherit}
.ieu-content table{border-collapse:collapse;width:100%;display:block;overflow-x:auto}
.ieu-content th,.ieu-content td{border:1px solid var(--line);padding:8px 10px}
.ieu-share{margin-top:36px;padding-top:24px;border-top:1px solid var(--line);display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap}
.ieu-share .cta{padding:10px 18px;border-radius:999px;background:var(--grad);color:#fff;text-decoration:none;font-weight:600;font-size:14px}
.ieu-foot{background:var(--night);color:#6f7d9c;font-size:13px}
.ieu-foot .wrap{display:flex;justify-content:space-between;align-items:center;gap:12px;padding-top:24px;padding-bottom:24px;flex-wrap:wrap}
.ieu-foot a{color:#aab6d1;text-decoration:none}
.ieu-foot .tl{font-family:var(--mono);letter-spacing:.14em;font-size:11px}
#ieu-hidden{display:none}
@media (max-width:900px){.ieu-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media (max-width:600px){.ieu-grid{grid-template-columns:minmax(0,1fr)}.ieu-links a:not(.cta){display:none}.ieu-article{padding:26px 20px;border-radius:18px}.ieu-hero{padding:48px 0 56px}}
